package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.common.Money;
import jakarta.persistence.AttributeOverride;
import jakarta.persistence.Column;
import jakarta.persistence.Embedded;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

import java.time.Instant;
import java.util.Objects;

/**
 * A request to move money from one Account to another, and where that request has got to.
 *
 * <p>A Transfer is a lifecycle rather than an outcome: it is created {@link
 * TransferStatus#PENDING} with the amount reserved on the source Account, and reaches
 * {@code SETTLED}, {@code REJECTED} or {@code EXPIRED} once its Checks are answered. Only
 * settlement moves money.
 *
 * <p><b>Two amounts, because the two Accounts may be denominated differently.</b> The
 * debited amount is what leaves the source Account, in the source Account's currency; the
 * credited amount is what arrives, in the destination Account's. A same-currency Transfer
 * carries the same figure twice, which is the honest reading — the conversion happened, at
 * a rate of one.
 *
 * <p><b>The Accounts are referenced by ID, not by association.</b> An Account is only ever
 * read or written under the pessimistic lock design decision 6 requires, and an
 * association would offer a second way to reach one that quietly skips it.
 *
 * <p>There is deliberately no method here that advances the status. Each transition is
 * owned by the ticket that has a caller for it — reserving (13), the Verdict that settles
 * or rejects (20), and expiry (23) — and each is a conditional update guarded on the
 * status it is leaving, so a transition written now would be a setter for three callers
 * that do not exist.
 */
@Entity
@Table(name = "transfers")
public class Transfer {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	private Long sourceAccountId;

	private Long destinationAccountId;

	@Embedded
	@AttributeOverride(name = "minorUnits", column = @Column(name = "debited_amount_minor_units"))
	@AttributeOverride(name = "currency", column = @Column(name = "debited_amount_currency"))
	private Money debitedAmount;

	@Embedded
	@AttributeOverride(name = "minorUnits", column = @Column(name = "credited_amount_minor_units"))
	@AttributeOverride(name = "currency", column = @Column(name = "credited_amount_currency"))
	private Money creditedAmount;

	// Left unannotated, JPA stores the status by ordinal. See design decision 29.
	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	private TransferStatus status;

	private Instant createdAt;

	private Instant statusChangedAt;

	protected Transfer() {
		// required by JPA
	}

	/**
	 * Requests a Transfer, which is the only way one comes into being: {@code PENDING},
	 * with both amounts already known because the Exchange Rate is locked at request time
	 * (design decision 15).
	 *
	 * <p>The instant is a parameter rather than an {@code Instant.now()} because the
	 * deadline expiry tests against is measured from it, and a clock a test can drive is
	 * the difference between asserting expiry and sleeping through it.
	 */
	public Transfer(Long sourceAccountId, Long destinationAccountId,
			Money debitedAmount, Money creditedAmount, Instant requestedAt) {
		this.sourceAccountId = Objects.requireNonNull(sourceAccountId, "a transfer leaves an account");
		this.destinationAccountId = Objects.requireNonNull(destinationAccountId, "a transfer arrives somewhere");
		this.debitedAmount = Objects.requireNonNull(debitedAmount, "a transfer moves an amount");
		this.creditedAmount = Objects.requireNonNull(creditedAmount, "a transfer credits an amount");
		this.createdAt = Objects.requireNonNull(requestedAt, "a transfer happens at a time");
		this.status = TransferStatus.PENDING;
		this.statusChangedAt = requestedAt;
	}

	public Long getId() {
		return id;
	}

	/** The Account the money leaves, and the one whose Reserved Amount holds it meanwhile. */
	public Long getSourceAccountId() {
		return sourceAccountId;
	}

	/** The Account the money arrives at, credited only at settlement. */
	public Long getDestinationAccountId() {
		return destinationAccountId;
	}

	/** What leaves the source Account, in the source Account's currency. */
	public Money getDebitedAmount() {
		return debitedAmount;
	}

	/** What reaches the destination Account, in the destination Account's currency. */
	public Money getCreditedAmount() {
		return creditedAmount;
	}

	public TransferStatus getStatus() {
		return status;
	}

	/** When the Transfer was requested. The Transactions list is ordered on it. */
	public Instant getCreatedAt() {
		return createdAt;
	}

	/**
	 * When the status last changed, which for a terminal Transfer is when it settled, was
	 * rejected or expired, and for a {@code PENDING} one is when it was requested.
	 *
	 * <p>Not a nullable "finished at": the status is the single answer to whether a
	 * Transfer is done, and a second column that also implies it is a second answer to
	 * keep in agreement with the first.
	 */
	public Instant getStatusChangedAt() {
		return statusChangedAt;
	}
}
package hu.bankmonitor.payments.transfers;

/**
 * Where a {@link Transfer} is in its lifecycle: {@link #PENDING} while its Checks are
 * outstanding, then one of the three terminal states.
 *
 * <p>The set is closed and the progression is one-way — a Transfer leaves {@code PENDING}
 * exactly once and never returns, which is what lets every advance be a conditional
 * update guarded on the status it is leaving. ADR-0001 has why the lifecycle exists at
 * all, and design decisions 7–15 are its mechanics.
 *
 * <p>Only {@link #SETTLED} moves money. All three terminal states release the source
 * Account's Reserved Amount.
 */
public enum TransferStatus {

	/** Requested, funds reserved, waiting on its Checks. The only non-terminal state. */
	PENDING,

	/** Every Check approved: the money moved. */
	SETTLED,

	/** A Check said no. The reservation is released and no money ever moved. */
	REJECTED,

	/** The Checks were not all answered in time. Releases the reservation, moves nothing. */
	EXPIRED
}
package hu.bankmonitor.payments.transfers;

import org.springframework.data.jpa.repository.JpaRepository;

/**
 * Reads and writes {@link Transfer}s.
 *
 * <p>Package-private on purpose, and that is the boundary rather than a convention:
 * design decision 30 keeps every repository uncallable from outside its own slice, so a
 * controller or another package cannot reach a Transfer except through the operations
 * this package declares. The compiler enforces it.
 *
 * <p>Nothing is declared here beyond what {@code JpaRepository} gives. The queries this
 * design calls for — the status filter, the newest-first listing, the reaper's overdue
 * scan, the conditional status update — each arrive with the ticket that has a caller to
 * shape them.
 */
interface TransferRepository extends JpaRepository<Transfer, Long> {
}
create table transfers (
    id                          bigint generated by default as identity primary key,

    source_account_id           bigint      not null,
    destination_account_id      bigint      not null,

    -- Four columns for two Money embeddables, named by Transfer's @AttributeOverrides.
    debited_amount_minor_units  bigint      not null,
    debited_amount_currency     varchar(3)  not null,
    credited_amount_minor_units bigint      not null,
    credited_amount_currency    varchar(3)  not null,

    status                      varchar(8)  not null,

    created_at                  timestamp(6) with time zone not null,
    status_changed_at           timestamp(6) with time zone not null,

    constraint transfers_source_account
        foreign key (source_account_id) references accounts (id),
    constraint transfers_destination_account
        foreign key (destination_account_id) references accounts (id),

    -- All three hold for rows the entity cannot write. Design decision 11.
    --
    -- `= any (array[…])` rather than `in (…)`: H2 compiles a constant `in` list into a set
    -- ordered by the session that parsed this file, and once Flyway's connection is gone
    -- every insert fails with "check constraint invalid" naming this constraint. An `or`
    -- chain folds into the same set. Design decision 11 has the measurement.
    constraint transfers_status_is_known
        check (status = any (array['PENDING', 'SETTLED', 'REJECTED', 'EXPIRED'])),
    constraint transfers_two_distinct_accounts
        check (source_account_id <> destination_account_id),
    constraint transfers_positive_amounts
        check (debited_amount_minor_units > 0 and credited_amount_minor_units > 0)
);

