20	/**
21	 * A request to move money from one Account to another, and where that request has got to.
22	 *
23	 * <p>A Transfer is a lifecycle rather than an outcome: it is created {@link
24	 * TransferStatus#PENDING} with the amount reserved on the source Account, and reaches
25	 * {@code SETTLED}, {@code REJECTED} or {@code EXPIRED} once its Checks are answered. Only
26	 * settlement moves money.
27	 *
28	 * <p><b>Two amounts, because the two Accounts may be denominated differently.</b> The
29	 * debited amount is what leaves the source Account, in the source Account's currency; the
30	 * credited amount is what arrives, in the destination Account's. A same-currency Transfer
31	 * carries the same figure twice, which is the honest reading — the conversion happened, at
32	 * a rate of one.
33	 *
34	 * <p><b>The Accounts are referenced by ID, not by association.</b> An Account is only ever
35	 * read or written under the pessimistic lock design decision 6 requires, and an
36	 * association would offer a second way to reach one that quietly skips it.
37	 *
38	 * <p>There is deliberately no method here that advances the status. Each transition is
39	 * owned by the ticket that has a caller for it — reserving (13), the Verdict that settles
40	 * or rejects (20), and expiry (23) — and each is a conditional update guarded on the
41	 * status it is leaving, so a transition written now would be a setter for three callers
42	 * that do not exist.
43	 *
44	 * <p>One timestamp, for the same reason: the status is the single answer to whether a
45	 * Transfer is done, and the ticket that first needs to know <em>when</em> it finished can
46	 * add that column with a reader to shape it.
47	 */
48	@Entity
49	@Table(name = "transfers")
50	public class Transfer {
51	
52		@Id
53		@GeneratedValue(strategy = GenerationType.IDENTITY)
54		private Long id;
55	
56		private Long sourceAccountId;
57	
58		private Long destinationAccountId;
59	
60		@Embedded
61		@AttributeOverride(name = "minorUnits", column = @Column(name = "debited_amount_minor_units"))
62		@AttributeOverride(name = "currency", column = @Column(name = "debited_amount_currency"))
63		private Money debitedAmount;
64	
65		@Embedded
66		@AttributeOverride(name = "minorUnits", column = @Column(name = "credited_amount_minor_units"))
67		@AttributeOverride(name = "currency", column = @Column(name = "credited_amount_currency"))
68		private Money creditedAmount;
69	
70		// If left unannotated, JPA stores the status by ordinal. See design decision 29.
71		@Enumerated(EnumType.STRING)
72		@JdbcTypeCode(SqlTypes.VARCHAR)
73		private TransferStatus status;
74	
75		private Instant createdAt;
76	
77		protected Transfer() {
78			// required by JPA
79		}
80	
81		/**
