87		 * deadline expiry tests against is measured from it, and a clock a test can drive is
88		 * the difference between asserting expiry and sleeping through it.
89		 */
90		public Transfer(Long sourceAccountId, Long destinationAccountId,
91				Money debitedAmount, Money creditedAmount, Instant requestedAt) {
92			this.sourceAccountId = Objects.requireNonNull(sourceAccountId, "a transfer leaves an account");
93			this.destinationAccountId = Objects.requireNonNull(destinationAccountId, "a transfer arrives somewhere");
94			this.debitedAmount = Objects.requireNonNull(debitedAmount, "a transfer moves an amount");
95			this.creditedAmount = Objects.requireNonNull(creditedAmount, "a transfer credits an amount");
96			this.createdAt = Objects.requireNonNull(requestedAt, "a transfer happens at a time");
97			this.status = TransferStatus.PENDING;
98		}
99	
100		public Long getId() {
101			return id;
102		}
103	
104		/** The Account the money leaves, and the one whose Reserved Amount holds it meanwhile. */
105		public Long getSourceAccountId() {
106			return sourceAccountId;
107		}
108	
109		/** The Account the money arrives at, credited only at settlement. */
110		public Long getDestinationAccountId() {
111			return destinationAccountId;
112		}
113	
114		/** What leaves the source Account, in the source Account's currency. */
115		public Money getDebitedAmount() {
116			return debitedAmount;
117		}
118	
119		/** What reaches the destination Account, in the destination Account's currency. */
120		public Money getCreditedAmount() {
121			return creditedAmount;
122		}
123	
124		public TransferStatus getStatus() {
125			return status;
126		}
127	
128		/** When the Transfer was requested. The Transactions list is ordered on it. */
129		public Instant getCreatedAt() {
